def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return min(budget, max(0, base))

    highest_prev_bid = None
    desperate_count = 0
    weak_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) < DAILY_SALARY * 2:
            weak_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            if highest_prev_bid is None or bid > highest_prev_bid:
                highest_prev_bid = bid

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0
    if supply_pressure > 1:
        supply_pressure = 1

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water >= 2:
        urgency += 0.35
    elif no_water >= 1:
        urgency += 0.18
    urgency += 0.22 * supply_pressure
    urgency += 0.05 * desperate_count
    urgency -= 0.04 * weak_count

    if day >= 8:
        urgency += 0.08

    if highest_prev_bid is not None:
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            if hp > 4 and no_water == 0:
                target = DAILY_SALARY * 0.28
            else:
                target = min(DAILY_SALARY * 0.98, highest_prev_bid + 1.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.65:
            target = max(DAILY_SALARY * 0.52, highest_prev_bid + 1.25)
        else:
            target = max(DAILY_SALARY * 0.42, highest_prev_bid + 1.0)
    else:
        target = DAILY_SALARY * (0.38 + urgency)

    if supply >= 22 and hp > 4 and no_water == 0:
        target *= 0.82
    elif supply <= 17:
        target *= 1.12

    reserve_floor = 0
    if day <= 7:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    affordable = budget - reserve_floor
    if affordable < 0:
        affordable = budget * 0.5

    bid = min(target, budget, max(0, affordable))

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))
    elif hp <= 4 or no_water >= 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.68))

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        # If no one else is alive, take enough to secure requirement while conserving budget.
        target = min(my_status['budget'], DAILY_SALARY * 0.4)
        return max(0.0, target)

    # Extract yesterday bids as immediate behavioral signal.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Fallback if no trace.
    if not yesterday_bids:
        # Conservative default: bid enough to likely clear but not overspend.
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        return min(my_status['budget'], DAILY_SALARY * 0.55)

    highest_prev_bid = max(yesterday_bids)
    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0)

    # Convert budget to a bid cap; keep within plausible water amounts.
    # We assume bids correlate with water allocation; aim around WATER_REQ.
    # Use supply bounds to avoid bidding above reasonable share.
    supply_cap = max(MIN_SUPPLY, min(MAX_SUPPLY, float(supply)))

    # Aggression thresholds: if opponents were bidding near our salary, scarcity pressure is high.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    if high_pressure:
        # If our HP is fragile, we must secure water.
        if my_hp <= 2:
            bid = min(my_budget, DAILY_SALARY * 0.95)
        else:
            # Otherwise, bid aggressively but not maximal.
            bid = min(my_budget, DAILY_SALARY * 0.35 + highest_prev_bid * 0.25)
    else:
        # Opponents were not fighting hard: underbid slightly above requirement.
        # Use their highest bid to stay competitive without wasting budget.
        base = max(WATER_REQ, highest_prev_bid + 1.0)
        # Cap by a fraction of salary to control spending.
        bid = min(my_budget, DAILY_SALARY * 0.55, base)

    # Ensure bid is within [0, supply_cap] range to avoid nonsensical oversized offers.
    if bid < 0:
        bid = 0.0
    bid = min(float(bid), float(supply_cap))

    # If we have consecutive no-water days, increase bid to prevent elimination.
    no_water_days = my_status.get('no_water_days', 0)
    if no_water_days >= 2:
        # Emergency: bid toward salary cap.
        bid = min(my_budget, DAILY_SALARY * (0.75 if my_hp > 2 else 0.95), float(supply_cap))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    # Determine base bid fraction
    if hp <= 2:
        bid_frac = 0.9
    elif hp <= 4:
        bid_frac = 0.6
    elif hp <= 6:
        bid_frac = 0.4
    else:
        bid_frac = 0.2
    # Increase aggression as days progress (last 3 days)
    if day >= 8:
        bid_frac = min(1.0, bid_frac + 0.2)
    elif day >= 5:
        bid_frac = min(1.0, bid_frac + 0.1)
    # Cap bid at budget and at salary
    bid = min(budget, DAILY_SALARY * bid_frac)
    # Ensure bid is positive
    bid = max(0.1, bid)
    return round(bid, 2)
